#### 215. 数组中的第K个最大元素
(https://leetcode.cn/problems/kth-largest-element-in-an-array/)
```cpp
class Solution {
  public:
	int findKthLargest(vector<int>& nums, int k) {
		priority_queue<int, vector<int>, std::greater<int>> pq;
		for_each(nums.begin(), nums.end(), [&pq, k](const int x) {
			if(pq.empty()) {
				pq.push(x);
			} else if(pq.size() < k && x > pq.top()) {
				pq.push(x);
			} else if(pq.size() >= k && x > pq.top()) {
				pq.push(x);
				pq.pop();
			} else if(pq.size() < k) {
				pq.push(x);
			}
		});
		return pq.top();
	}
};

// 简化版
class Solution {
  public:
	int findKthLargest(vector<int>& nums, int k) {
		priority_queue<int, vector<int>, std::greater<int>> pq;
		for_each(nums.begin(), nums.end(), [&pq, k](const int x) {
			pq.push(x);
            if (pq.size() > k) {
                pq.pop();
            }
		});
		return pq.top();
	}
};
```
